using System;
using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine.TestTools;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
namespace Wildfolk.Tests
{
    public sealed class CharacterPassPlayTests
    {
        private WorldSaveService save;private PlayerInventory player;private PlayerEquipment equipment;private PlayerProgression growth;private PlayerLocomotion move;private GameplaySession session;private PlayPointerDriver input;
        private sealed class MoveSource:IPlayerInputSource {public Vector2 Direction;public Vector2 Move=>Direction;public bool Primary=>false;public bool Interact=>false;public bool Inventory=>false;public bool Pause=>false;}
        [UnitySetUp]public IEnumerator Setup()
        {Time.timeScale=1;input=new PlayPointerDriver();WorldGenerator.SelectedSeed=9472026;yield return SceneManager.LoadSceneAsync("Wildfolk");yield return null;yield return null;save=UnityEngine.Object.FindFirstObjectByType<WorldSaveService>();save.AutoSaveEnabled=false;player=save.Player;equipment=player.GetComponent<PlayerEquipment>();growth=player.GetComponent<PlayerProgression>();move=player.GetComponent<PlayerLocomotion>();session=save.World.Session;save.Clock.enabled=false;save.GetComponent<ZombieSpawner>().enabled=false;save.GetComponent<GoblinSpawner>().enabled=false;save.World.Renewal.enabled=false;save.World.Animals.enabled=false;foreach(var n in UnityEngine.Object.FindObjectsByType<ResourceNode>(FindObjectsSortMode.None))if(n.transform.position.sqrMagnitude<144)n.gameObject.SetActive(false);Position(Vector2.zero);}
        [UnityTearDown]public IEnumerator Teardown(){Time.timeScale=1;input.Dispose();yield return null;}
        private void Position(Vector2 p){player.transform.position=p;player.GetComponent<Rigidbody2D>().position=p;player.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
        private void Equip(string id){var item=save.Catalog.Item(id);player.Model.Add(item,1);Assert.That(equipment.TryEquip(item),Is.True);}
        [UnityTest]public IEnumerator ArmorBothSlotsReduceDamagePreserveMinimumAndSurvivalBypass()
        {Equip("leather_head");Equip("leather_body");var h=player.GetComponent<Health>();Assert.That(equipment.Defense,Is.EqualTo(3));Assert.That(h.ApplyDamage(8),Is.EqualTo(5));Assert.That(h.ApplyDamage(2,true),Is.EqualTo(2));Equip("iron_head");Equip("iron_body");Assert.That(equipment.Defense,Is.EqualTo(6));Assert.That(h.ApplyDamage(8),Is.EqualTo(2));Assert.That(h.ApplyDamage(1),Is.EqualTo(1));Assert.That(player.Model.CountItem(save.Catalog.Item("leather_head")),Is.EqualTo(1));Assert.That(equipment.Unequip(ArmorSlot.Head),Is.True);Assert.That(equipment.Defense,Is.EqualTo(4));Assert.That(equipment.HeadVisual.enabled,Is.False);Assert.That(equipment.Unequip(ArmorSlot.Body),Is.True);Assert.That(equipment.Defense,Is.Zero);yield return null;}
        [UnityTest]public IEnumerator GrowthSkillsEquipmentAndStaminaSurviveValidatedSaveRoundTrip()
        {growth.SetValues(450,17);Assert.That(growth.Level,Is.EqualTo(6));for(var i=0;i<4;i++)Assert.That(growth.Invest(i),Is.True);yield return null;Equip("iron_head");Equip("iron_body");player.GetComponent<Health>().RestoreHealth(107);move.Restore(62,.7f);var snapshot=SaveRepository.Decode(SaveRepository.Encode(save.Capture()));save.Validate(snapshot);growth.SetValues(0,0);equipment.RestoreArmor(null,null);save.Apply(snapshot);Assert.That(growth.Level,Is.EqualTo(6));Assert.That(growth.CurrentXP,Is.EqualTo(75));Assert.That(growth.SkillPoints,Is.EqualTo(1));Assert.That(player.GetComponent<Health>().Maximum,Is.EqualTo(110));Assert.That(player.GetComponent<Health>().Current,Is.EqualTo(107));Assert.That(move.Stamina.Maximum,Is.EqualTo(115));Assert.That(move.Stamina.Current,Is.EqualTo(62));Assert.That(equipment.Defense,Is.EqualTo(6));Assert.That(player.GetComponent<CharacterStats>().RecoveryMultiplier,Is.GreaterThan(1));Assert.That(player.GetComponent<CharacterStats>().SprintCostMultiplier,Is.LessThan(1));yield return null;}
        [UnityTest]public IEnumerator V1MigrationPreservesWorldInventoryAndOldXPWithoutForcingNewGame()
        {player.Model.Add(save.Catalog.Item("wood"),17);growth.SetValues(123,9);var old=save.Capture();old.Version=1;old.Animals=new[]{new AnimalSnapshot{Id="a0_0",Rule=0,HP=10,Position=new Vector2(-12,-5),Home=new Vector2(-12,-5)},new AnimalSnapshot{Id="a1_0",Rule=1,HP=20,Position=new Vector2(14,-6),Home=new Vector2(14,-6)}};old.Player.Growth=null;old.Player.Stamina=0;var decoded=SaveRepository.Decode(SaveRepository.Encode(old));save.Validate(decoded);Assert.That(decoded.Version,Is.EqualTo(5));Assert.That(decoded.Player.Growth.Level,Is.EqualTo(3));Assert.That(decoded.Player.Growth.CurrentXP,Is.EqualTo(33));Assert.That(decoded.Player.Growth.Points,Is.EqualTo(2));save.Apply(decoded);Assert.That(player.Model.CountItem(save.Catalog.Item("wood")),Is.EqualTo(17));Assert.That(growth.Experience,Is.EqualTo(123));Assert.That(growth.Gold,Is.EqualTo(9));Assert.That(move.Stamina.Current,Is.EqualTo(100));yield return null;}
        [UnityTest]public IEnumerator ProfileOpensIndependentTreeAndInventoryOwnsEquipment()
        {player.Model.Add(save.Catalog.Item("leather_head"),1);growth.SetValues(35,0);var hud=UnityEngine.Object.FindFirstObjectByType<ProfileHud>();yield return input.Click(hud.Level.transform.parent.GetComponent<Button>());var screen=UnityEngine.Object.FindFirstObjectByType<CharacterScreen>();Assert.That(session.State,Is.EqualTo(SessionState.Character));Assert.That(move.TryDash(),Is.False);yield return input.Click(screen.TreeButton);var tree=UnityEngine.Object.FindFirstObjectByType<SkillTreeScreen>();Assert.That(session.State,Is.EqualTo(SessionState.SkillTree));yield return input.Click(tree.Nodes[0]);yield return input.Click(tree.InvestButton);Assert.That(growth.Rank(0),Is.EqualTo(1));tree.Close();session.OpenInventory();var equipmentView=UnityEngine.Object.FindFirstObjectByType<InventoryEquipment>();for(var i=0;i<player.Model.Capacity;i++)if(!player.Model.GetSlot(i).IsEmpty && player.Model.GetSlot(i).Item.Id=="leather_head")player.SelectSlot(i);yield return null;Assert.That(equipmentView.Comparison.text,Does.Contain("0 → 1"));yield return input.Click(equipmentView.EquipButton);Assert.That(equipment.HeadArmor.Id,Is.EqualTo("leather_head"));yield return input.Click(equipmentView.HeadButton);Assert.That(equipmentView.SlotFilter,Is.EqualTo((int)ArmorSlot.Head));Assert.That(equipmentView.Panel.SelectedName.text,Is.EqualTo(save.Catalog.Item("leather_head").LocalizedName));yield return input.Click(equipmentView.UnequipButton);Assert.That(equipment.HeadArmor,Is.Null);Assert.That(player.Model.CountItem(save.Catalog.Item("leather_head")),Is.EqualTo(1));yield return input.Click(equipmentView.Panel.Slots[0]);Assert.That(equipmentView.Panel.SelectedName.text,Is.EqualTo(save.Catalog.Item("leather_head").LocalizedName));Assert.That(equipmentView.EquipButton.gameObject.activeSelf,Is.True);session.CloseInventory();}
        [UnityTest]public IEnumerator SprintThroughInputDrainsStopsAtCriticalNeedsAndHUDHidesAfterRecovery()
        {var source=new MoveSource{Direction=Vector2.right};player.GetComponent<PlayerInputAdapter>().Source=source;yield return new WaitForSeconds(.48f);Assert.That(move.Stamina.IsSprinting,Is.True);Assert.That(move.Stamina.Current,Is.LessThan(100));var hud=UnityEngine.Object.FindFirstObjectByType<PlayerStaminaHud>();Assert.That(hud.Group.alpha,Is.GreaterThan(0));player.GetComponent<PlayerSurvival>().Model.SetMeters(20,80);yield return null;Assert.That(move.Stamina.IsSprinting,Is.False);source.Direction=Vector2.zero;move.Restore(100,0);yield return new WaitForSeconds(1.1f);Assert.That(hud.Group.alpha,Is.Zero);}
        [UnityTest]public IEnumerator DashUsesFacingAndMovementDirectionCostsStaminaAndStopsAtWall()
        {player.GetComponent<PlayerAvatar>().Facing.Face(Vector2.left);Assert.That(move.TryDash(),Is.True);Assert.That(move.DashDirection,Is.EqualTo(Vector2.left));Assert.That(move.Stamina.Current,Is.EqualTo(76));yield return new WaitForSeconds(.22f);Assert.That(player.transform.position.x,Is.LessThan(-2));yield return new WaitForSeconds(.4f);Position(Vector2.zero);var source=new MoveSource{Direction=Vector2.right};player.GetComponent<PlayerInputAdapter>().Source=source;yield return null;player.GetComponent<PlayerInputAdapter>().Source=null;var wall=UnityEngine.Object.Instantiate(save.Catalog.Item("wood_wall").Placement.Prefab,new Vector2(1.8f,0),Quaternion.identity);Physics2D.SyncTransforms();Assert.That(move.TryDash(),Is.True);Assert.That(move.DashDirection,Is.EqualTo(Vector2.right));yield return new WaitForSeconds(.22f);Assert.That(player.transform.position.x,Is.LessThan(.5f));Assert.That(move.IsDashing,Is.False);move.Restore(10,0);Assert.That(move.TryDash(),Is.False);yield return null;}
        [UnityTest]public IEnumerator DashCannotCrossDeepWaterAndCannotRunWithInventoryOrPauseOpen()
        {var nav=player.GetComponent<PlayerMotor>().Terrain;Vector2 shore=Vector2.zero;var found=false;for(var y=-55;y<55 && !found;y++)for(var x=-70;x<70;x++){var p=new Vector2(x,y);if(nav.Traversable(p,.6f) && save.World.Map.IsDeepWater(p+Vector2.right*2)){shore=p;found=true;break;}}Assert.That(found,Is.True);Position(shore);player.GetComponent<PlayerAvatar>().Facing.Face(Vector2.right);Assert.That(move.TryDash(),Is.True);yield return new WaitForSeconds(.22f);Assert.That(nav.Traversable(player.transform.position,.55f),Is.True);Assert.That(save.World.Map.IsDeepWater(player.transform.position),Is.False);session.OpenInventory();var before=move.Stamina.Current;Assert.That(move.TryDash(),Is.False);Assert.That(move.Stamina.Current,Is.EqualTo(before));session.OpenPause();Assert.That(move.TryDash(),Is.False);session.Resume();}
        [UnityTest]public IEnumerator WorkbenchUpgradeKeepsTierIRecipesAndPersistsTierIIChestContents()
        {var bench=UnityEngine.Object.Instantiate(save.Catalog.Item("workbench").Placement.Prefab,new Vector2(2,0),Quaternion.identity).GetComponent<CraftingStation>();yield return null;var crafting=player.GetComponent<PlayerCrafting>();crafting.OpenStation(bench);var nextRecipe=save.Catalog.Recipe("reinforced_chest");Assert.That(crafting.GetStatus(nextRecipe),Is.EqualTo(CraftStatus.StationRequired));crafting.MarkSeen(nextRecipe);Assert.That(crafting.UpgradeWorkbench(),Is.False);foreach(var cost in bench.Definition.UpgradeCosts)player.Model.Add(cost.Item,cost.Count);var id=bench.GetComponent<WorldPlaceable>().SaveId;Assert.That(crafting.UpgradeWorkbench(),Is.True);Assert.That(crafting.Station.Definition.WorkbenchTier,Is.EqualTo(2));Assert.That(crafting.Station.GetComponent<WorldPlaceable>().SaveId,Is.EqualTo(id));player.Model.Add(save.Catalog.Item("wood"),25);player.Model.Add(save.Catalog.Item("iron_ingot"),2);Assert.That(crafting.GetStatus(save.Catalog.Recipe("axe")),Is.EqualTo(CraftStatus.Ready));Assert.That(crafting.IsNew(nextRecipe),Is.True);var before=UnityEngine.Object.FindFirstObjectByType<CraftingPanel>().Cards.Select(c=>c.Recipe.Id).ToArray();Assert.That(crafting.Craft(nextRecipe),Is.EqualTo(CraftStatus.Ready));crafting.MarkSeen(nextRecipe);Assert.That(crafting.IsNew(nextRecipe),Is.False);Assert.That(UnityEngine.Object.FindFirstObjectByType<CraftingPanel>().Cards.Select(c=>c.Recipe.Id).ToArray(),Is.EqualTo(before));var chest=UnityEngine.Object.Instantiate(nextRecipe.Result.Placement.Prefab,new Vector2(-2,0),Quaternion.identity).GetComponent<StorageChest>();yield return null;Assert.That(chest.Model.Capacity,Is.EqualTo(32));chest.Model.Add(save.Catalog.Item("wood"),17);session.CloseInventory();save.Apply(SaveRepository.Decode(SaveRepository.Encode(save.Capture())));yield return null;var restored=UnityEngine.Object.FindObjectsByType<CraftingStation>(FindObjectsSortMode.None).Single(s=>s.Definition.Station==StationKind.Workbench);Assert.That(restored.Definition.WorkbenchTier,Is.EqualTo(2));Assert.That(restored.GetComponent<WorldPlaceable>().SaveId,Is.EqualTo(id));var restoredChest=UnityEngine.Object.FindFirstObjectByType<StorageChest>();Assert.That(restoredChest.Model.Capacity,Is.EqualTo(32));Assert.That(restoredChest.Model.CountItem(save.Catalog.Item("wood")),Is.EqualTo(17));}
        [UnityTest]public IEnumerator DeveloperProfilesUseCurrentDataRemainEditorOnlyAndDashButtonRuns()
        {
            Type harness=null;foreach(var assembly in AppDomain.CurrentDomain.GetAssemblies()){var type=assembly.GetType("Wildfolk.Editor.DeveloperHarness");if(type!=null)harness=type;}Assert.That(harness,Is.Not.Null);Assert.That(harness.Assembly.GetName().Name,Is.EqualTo("Assembly-CSharp-Editor"));
            for(var rank=1;rank<=4;rank++){var profile=UnityEditor.AssetDatabase.LoadAssetAtPath<ScriptableObject>("Assets/Wildfolk/Data/DeveloperProfile"+rank+".asset");Assert.That(profile,Is.Not.Null);harness.GetMethod("LoadProfile").Invoke(null,new object[]{profile});Assert.That(player.Model.CountItem(save.Catalog.Item("wood")),Is.GreaterThan(0));Assert.That(growth.SkillPoints,Is.EqualTo((growth.Level-1)*growth.Definition.PointsPerLevel));save.Validate(save.Capture());}
            Assert.That(UnityEngine.Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None).Any(c=>c.GetType().Name.Contains("Developer")),Is.False);
            var hud=UnityEngine.Object.FindFirstObjectByType<GameplayHud>();player.GetComponent<PlayerAvatar>().Facing.Face(Vector2.left);yield return input.Click(hud.GetComponent<ControlSizeLayout>().Dash.GetComponent<Button>());Assert.That(move.Stamina.Current,Is.LessThan(80));Assert.That(move.DashDirection,Is.EqualTo(Vector2.left));yield return new WaitForSeconds(.22f);Assert.That(player.transform.position.x,Is.LessThan(-2));
        }
        [UnityTest]public IEnumerator CraftingCategoriesAndCraftableFilterReflectActualRecipes()
        {var bench=UnityEngine.Object.Instantiate(save.Catalog.Item("workbench_ii").Placement.Prefab,new Vector2(2,0),Quaternion.identity).GetComponent<CraftingStation>();yield return null;player.GetComponent<PlayerCrafting>().OpenStation(bench);var panel=UnityEngine.Object.FindFirstObjectByType<CraftingPanel>();yield return input.Click(panel.CategoryButtons[(int)RecipeCategory.Tools+1]);Assert.That(panel.Cards.Where(c=>c.gameObject.activeSelf).All(c=>c.Recipe.Category==RecipeCategory.Tools),Is.True);panel.ToggleFilter();Assert.That(panel.Cards.Any(c=>c.gameObject.activeSelf),Is.False);player.Model.Add(save.Catalog.Item("wood"),5);Assert.That(panel.Cards.Any(c=>c.gameObject.activeSelf),Is.True);Assert.That(panel.Cards.Where(c=>c.gameObject.activeSelf).All(c=>c.Crafting.GetStatus(c.Recipe)==CraftStatus.Ready),Is.True);}
    }
}
